'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { MailIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';

import { rowCollapseOf } from './_parts/collapse';
import { MEMBERS, type Member, type Role } from './_parts/people';
import { PresenceAvatar } from './_parts/presence-avatar';
import { RoleMenu } from './_parts/role-menu';
import { SlidingCount } from './_parts/sliding-count';
import { memberCountLabelOf } from './_parts/teams';

type Invitation = { id: string; email: string; sentLabel: string };

const INITIAL_MEMBERS = MEMBERS.slice(0, 5);

const INITIAL_INVITATIONS: Invitation[] = [
  { id: 'priya', email: 'priya@example.com', sentLabel: 'Invited 2 days ago' },
];

function invitedLabelOf(count: number) {
  if (count === 0) {
    return 'no pending invite';
  }
  if (count === 1) {
    return '1 invited';
  }
  return `${count} invited`;
}

function withRole(members: Member[], memberId: string, role: Role) {
  return members.map((member) => {
    if (member.id !== memberId) {
      return member;
    }
    return { ...member, role };
  });
}

/** You leave a team from its settings, never by removing yourself from the list. */
function removalOf(member: Member, remove: () => void) {
  if (member.isYou) {
    return undefined;
  }
  return remove;
}

function managerCountOf(members: Member[]) {
  return members.filter((member) => member.role === 'manager').length;
}

type MemberRowProps = {
  member: Member;
  isLastManager: boolean;
  onRoleChange: (memberId: string, role: Role) => void;
  onRemove: (memberId: string) => void;
};

function MemberRow({
  member,
  isLastManager,
  onRoleChange,
  onRemove,
}: MemberRowProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  function changeRole(role: Role) {
    onRoleChange(member.id, role);
  }

  function remove() {
    onRemove(member.id);
  }

  return (
    <motion.li
      variants={rowCollapseOf(shouldReduceMotion)}
      initial='hidden'
      animate='shown'
      exit='hidden'
      className='overflow-hidden'
    >
      <div className='flex items-center gap-3 py-2'>
        <PresenceAvatar member={member} size='sm' />
        <div className='min-w-0 flex-1'>
          <p className='flex items-center gap-1.5 text-[13px] leading-5 font-medium'>
            <span className='truncate'>{member.name}</span>
            {member.isYou && <Badge variant='secondary'>You</Badge>}
          </p>
          <p className='text-muted-foreground truncate text-xs'>
            {member.email}
          </p>
        </div>
        <RoleMenu
          role={member.role}
          memberName={member.name}
          isLastManager={isLastManager}
          onChange={changeRole}
          onRemove={removalOf(member, remove)}
          trigger='text'
        />
      </div>
    </motion.li>
  );
}

function InvitationRow({
  invitation,
  onRevoke,
}: {
  invitation: Invitation;
  onRevoke: (invitationId: string) => void;
}) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.li
      variants={rowCollapseOf(shouldReduceMotion)}
      initial='hidden'
      animate='shown'
      exit='hidden'
      className='overflow-hidden'
    >
      <div className='flex items-center gap-3 py-2'>
        <span className='hairline-border text-muted-foreground border-foreground/25 flex size-7 shrink-0 items-center justify-center rounded-full border-dashed'>
          <MailIcon className='size-3.5' />
        </span>
        <div className='min-w-0 flex-1'>
          <p className='truncate text-[13px] leading-5 font-medium'>
            {invitation.email}
          </p>
          <p className='text-muted-foreground truncate text-xs'>
            {invitation.sentLabel}
          </p>
        </div>
        <Button
          variant='ghost'
          size='sm'
          aria-label={`Revoke the invite to ${invitation.email}`}
          onClick={() => onRevoke(invitation.id)}
          className='text-muted-foreground'
        >
          <XIcon />
          Revoke
        </Button>
      </div>
    </motion.li>
  );
}

export default function Teams04() {
  const titleId = useId();
  const [members, setMembers] = useState(INITIAL_MEMBERS);
  const [invitations, setInvitations] = useState(INITIAL_INVITATIONS);
  const managerCount = managerCountOf(members);
  const hasOneManager = managerCount === 1;

  function changeRole(memberId: string, role: Role) {
    setMembers((current) => withRole(current, memberId, role));
  }

  function remove(memberId: string) {
    setMembers((current) => current.filter((member) => member.id !== memberId));
  }

  function revoke(invitationId: string) {
    setInvitations((current) =>
      current.filter((invitation) => invitation.id !== invitationId)
    );
  }

  return (
    <section
      aria-labelledby={titleId}
      className='bg-card hairline-ring ring-border w-full max-w-[30rem] rounded-xl px-4 pt-3.5 pb-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <header className='flex items-baseline justify-between gap-3 pb-1'>
        <h3 id={titleId} className='text-sm font-medium'>
          Members of Atlas Redesign
        </h3>
        <p className='text-muted-foreground flex gap-1 text-xs'>
          <SlidingCount value={members.length} format={memberCountLabelOf} />
          <span aria-hidden='true'>·</span>
          <SlidingCount value={invitations.length} format={invitedLabelOf} />
        </p>
      </header>
      <ul aria-label='Members'>
        <AnimatePresence initial={false}>
          {members.map((member) => {
            const isManager = member.role === 'manager';
            const isLastManager = isManager && hasOneManager;
            return (
              <MemberRow
                key={member.id}
                member={member}
                isLastManager={isLastManager}
                onRoleChange={changeRole}
                onRemove={remove}
              />
            );
          })}
          {invitations.map((invitation) => (
            <InvitationRow
              key={invitation.id}
              invitation={invitation}
              onRevoke={revoke}
            />
          ))}
        </AnimatePresence>
      </ul>
    </section>
  );
}

import type { Transition, Variants } from 'motion/react';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

/**
 * The spring AnimatedSize resizes with. It starts from rest, so the fade leads and the freed space
 * closes after it at the pace the surrounding container follows, instead of snapping shut.
 */
const SIZE_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.32 };

const ARRIVE: Transition = {
  ...SIZE_SPRING,
  opacity: { duration: 0.2, ease: EASE_OUT_STRONG },
};

const LEAVE: Transition = {
  ...SIZE_SPRING,
  opacity: { duration: 0.12, ease: EASE_OUT_STRONG },
};

const ARRIVE_FADE: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const LEAVE_FADE: Transition = { duration: 0.12, ease: EASE_OUT_STRONG };

/** A row whose spacing sits inside it: only its height and opacity change. */
const ROW_VARIANTS: Variants = {
  shown: { height: 'auto', opacity: 1, transition: ARRIVE },
  hidden: { height: 0, opacity: 0, transition: LEAVE },
};

/** A padded surface dismissed for good: its padding closes with its height. */
const SURFACE_VARIANTS: Variants = {
  shown: { height: 'auto', opacity: 1, transition: ARRIVE },
  hidden: {
    height: 0,
    opacity: 0,
    paddingTop: 0,
    paddingBottom: 0,
    transition: LEAVE,
  },
};

const FADE_VARIANTS: Variants = {
  shown: { opacity: 1, transition: ARRIVE_FADE },
  hidden: { opacity: 0, transition: LEAVE_FADE },
};

export function rowCollapseOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ROW_VARIANTS;
}

export function surfaceCollapseOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SURFACE_VARIANTS;
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

const ARRIVE: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const LEAVE: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const BLUR_VARIANTS: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)', transition: ARRIVE },
  exit: { opacity: 0, filter: 'blur(2px)', transition: LEAVE },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: ARRIVE },
  exit: { opacity: 0, transition: LEAVE },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return BLUR_VARIANTS;
}

type MorphLabelProps = {
  /** Changes when the label becomes another one. */
  value: string;
  className?: string;
  children: React.ReactNode;
};

/** A label that becomes another: the text crossfades through a light blur while its width follows. */
export function MorphLabel({ value, className, children }: MorphLabelProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={value}
          variants={variantsOf(shouldReduceMotion)}
          initial='enter'
          animate='visible'
          exit='exit'
          className={cn('flex whitespace-nowrap', className)}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

