import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';

import { PRESENCE_META, type Member } from './people';

const SIZE_CLASS = {
  sm: { avatar: 'size-7', badge: 'size-3.5', glyph: 'size-2' },
  md: { avatar: 'size-9', badge: 'size-4', glyph: 'size-2.5' },
  lg: { avatar: 'size-12', badge: 'size-5', glyph: 'size-3' },
} as const;

type PresenceAvatarProps = {
  member: Member;
  size?: keyof typeof SIZE_CLASS;
  /** The colour behind the badge's cut-out: the surface the avatar sits on. */
  surfaceClassName?: string;
  className?: string;
};

/** A person's face with their presence as a small glyph on its corner, read out after the name. */
export function PresenceAvatar({
  member,
  size = 'md',
  surfaceClassName = 'bg-card',
  className,
}: PresenceAvatarProps) {
  const presence = PRESENCE_META[member.presence];
  const Glyph = presence.glyph;
  const badgeStyle = { '--chip': presence.color } as React.CSSProperties;
  const sizes = SIZE_CLASS[size];

  return (
    <span className={cn('relative inline-flex shrink-0', className)}>
      <Avatar className={sizes.avatar} seed={member.name} />
      <span
        aria-hidden='true'
        className={cn(
          'absolute -end-0.5 -bottom-0.5 flex rounded-full p-px',
          surfaceClassName
        )}
      >
        <span
          style={badgeStyle}
          className={cn(
            'chip-3d flex items-center justify-center rounded-full',
            sizes.badge
          )}
        >
          <Glyph className={sizes.glyph} strokeWidth={2.75} />
        </span>
      </span>
      <span className='sr-only'>{presence.label}</span>
    </span>
  );
}

'use client';

import { ChevronDownIcon, UserMinusIcon } from '@/registry/ndeko/lib/icons';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuGroupLabel,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import { MorphLabel } from './morph-label';
import { ROLE_META, ROLE_ORDER, isRole, type Role } from './people';

type RoleTrigger = 'chip' | 'text';

const CHIP_TRIGGER =
  'chip-3d inline-flex h-6 shrink-0 cursor-pointer items-center gap-1 rounded-md px-2 text-xs font-medium whitespace-nowrap outline-none focus-visible:ring-[3px] focus-visible:ring-ring/25';

const TEXT_TRIGGER =
  'inline-flex h-7 shrink-0 cursor-pointer items-center gap-1 rounded-md px-2 text-[13px] whitespace-nowrap text-muted-foreground outline-none transition-colors duration-150 hover:bg-foreground/5 hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/25 data-popup-open:bg-foreground/5 data-popup-open:text-foreground';

function triggerClassOf(trigger: RoleTrigger) {
  if (trigger === 'chip') {
    return CHIP_TRIGGER;
  }
  return TEXT_TRIGGER;
}

function triggerStyleOf(trigger: RoleTrigger, role: Role) {
  if (trigger === 'chip') {
    return { '--chip': ROLE_META[role].color } as React.CSSProperties;
  }
  return undefined;
}

function isLockedOption(option: Role, isLastManager: boolean) {
  const leavesManagerRole = option !== 'manager';
  return isLastManager && leavesManagerRole;
}

type RoleMenuProps = {
  role: Role;
  memberName: string;
  onChange: (role: Role) => void;
  /** The only manager of the team cannot step down: a team keeps one. */
  isLastManager?: boolean;
  /** Adds Remove from team at the end of the menu. */
  onRemove?: () => void;
  trigger?: RoleTrigger;
};

/** The role of a member as a menu: the trigger shows it, the rows explain each one. */
export function RoleMenu({
  role,
  memberName,
  onChange,
  isLastManager = false,
  onRemove,
  trigger = 'chip',
}: RoleMenuProps) {
  const meta = ROLE_META[role];
  const canRemove = onRemove !== undefined;
  const triggerLabel = `Role of ${memberName}: ${meta.label}. Change role`;

  function changeRole(value: unknown) {
    if (isRole(value)) {
      onChange(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={triggerLabel}
        style={triggerStyleOf(trigger, role)}
        className={triggerClassOf(trigger)}
      >
        <MorphLabel value={role}>{meta.label}</MorphLabel>
        <ChevronDownIcon className='size-3.5 opacity-70' />
      </DropdownMenuTrigger>
      <DropdownMenuContent align='end' className='w-72'>
        <DropdownMenuGroup>
          <DropdownMenuGroupLabel>Role of {memberName}</DropdownMenuGroupLabel>
          <DropdownMenuRadioGroup value={role} onValueChange={changeRole}>
            {ROLE_ORDER.map((option) => {
              const optionMeta = ROLE_META[option];
              const isLocked = isLockedOption(option, isLastManager);
              return (
                <DropdownMenuRadioItem
                  key={option}
                  value={option}
                  disabled={isLocked}
                  closeOnClick
                  className='h-auto items-start py-2'
                >
                  <span className='flex flex-col gap-0.5'>
                    <span>{optionMeta.label}</span>
                    <span className='text-muted-foreground text-xs'>
                      {optionMeta.description}
                    </span>
                  </span>
                </DropdownMenuRadioItem>
              );
            })}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
        {isLastManager && (
          <p className='text-muted-foreground px-2 pt-1 pb-1.5 text-xs'>
            A team keeps at least one manager. Make someone else a manager first
          </p>
        )}
        {canRemove && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem variant='destructive' onClick={onRemove}>
              <UserMinusIcon />
              Remove from team
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

const SHIFT_PX = 8;

const SLIDE_TRANSITION: Transition = { duration: 0.18, ease: [0.2, 0, 0, 1] };

const SLIDE_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * SHIFT_PX;
    return { opacity: 0, y: offset };
  },
  visible: { opacity: 1, y: 0 },
  exit: (direction: number) => {
    const offset = direction * SHIFT_PX;
    return { opacity: 0, y: -offset };
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SLIDE_VARIANTS;
}

function directionOf(previous: number, next: number) {
  if (next > previous) {
    return 1;
  }
  return -1;
}

type Shown = { value: number; direction: number };

type SlidingCountProps = {
  value: number;
  /** Writes the figure in words, with its singular branch. */
  format: (value: number) => string;
  className?: string;
};

/** A figure the person just changed: it slides in the direction of the change. */
export function SlidingCount({ value, format, className }: SlidingCountProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [shown, setShown] = useState<Shown>({ value, direction: 1 });
  const text = format(value);

  if (shown.value !== value) {
    const direction = directionOf(shown.value, value);
    setShown({ value, direction });
  }

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence
        mode='popLayout'
        initial={false}
        custom={shown.direction}
      >
        <motion.span
          key={text}
          custom={shown.direction}
          variants={variantsOf(shouldReduceMotion)}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SLIDE_TRANSITION}
          className='whitespace-nowrap'
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

